     9→/**
    10→ * Mini Java Application with intentional containerization blockers for testing
    11→ */
    12→public class MiniApp {
    13→    
    14→    // Container-friendly port configuration
    15→    private static final int SERVER_PORT = Integer.parseInt(System.getenv().getOrDefault("SERVER_PORT", "8080"));
    16→    
    17→    // Container-friendly configuration path using environment variables
    18→    private static final String CONFIG_FILE_PATH = System.getenv().getOrDefault("CONFIG_PATH", "application.properties");
    19→    private static final String LOG_LEVEL = System.getenv().getOrDefault("LOG_LEVEL", "INFO");
    20→    
    21→    private HealthController healthController;
    22→    
    23→    public static void main(String[] args) {
    24→        System.out.println("Starting Mini Java Application...");
