    28→        app.startHealthCheckServer();
    29→        app.startServer();
    30→    }
    31→    
    32→    private void initializeApplication() {
    33→        // BLOCKER: Reading from hardcoded absolute path
    34→        loadConfiguration();
    35→        
    36→        // BLOCKER: Writing to hardcoded absolute path
    37→        initializeLogging();
    38→        
    39→        // Initialize database connection with hardcoded values
    40→        DatabaseService dbService = new DatabaseService();
    41→        dbService.connect();
    42→    }
    43→    
    44→    private void loadConfiguration() {
    45→        try {
    46→            // Container-friendly configuration loading with fallback
    47→            Properties props = new Properties();
    48→            
    49→            // Try loading from classpath first (container-friendly)
    50→            try (var stream = getClass().getClassLoader().getResourceAsStream(CONFIG_FILE_PATH)) {
    51→                if (stream != null) {
    52→                    props.load(stream);
    53→                    System.out.println("Configuration loaded from classpath: " + CONFIG_FILE_PATH);
    54→                } else {
    55→                    // Fallback to file system if classpath loading fails
    56→                    File configFile = new File(CONFIG_FILE_PATH);
    57→                    if (configFile.exists()) {
    58→                        props.load(new FileInputStream(configFile));
    59→                        System.out.println("Configuration loaded from file: " + CONFIG_FILE_PATH);
    60→                    } else {
    61→                        System.out.println("Warning: Configuration file not found, using defaults");
    62→                    }
    63→                }
    64→            }
    65→            
    66→            // Log configuration info to console (container-friendly)
    67→            System.out.println("Configuration loaded successfully");
    68→            
    69→        } catch (IOException e) {
    70→            System.err.println("Failed to load configuration: " + e.getMessage());
    71→        }
    72→    }
    73→    
    74→    private void initializeLogging() {
    75→        // Container-friendly logging - output to console instead of files
    76→        System.out.println("Logging initialized - outputting to console (container-friendly)");
    77→        System.out.println("Log level: " + LOG_LEVEL);
    78→        
    79→        // Set up console-based logging configuration
    80→        System.setProperty("java.util.logging.ConsoleHandler.level", LOG_LEVEL);
    81→        System.setProperty("java.util.logging.ConsoleHandler.formatter", "java.util.logging.SimpleFormatter");
    82→        
    83→        // Log initialization message
    84→        logInfo("Application logging configured for container environment");
    85→    }
    86→    
    87→    private void logInfo(String message) {
    88→        System.out.println("[INFO] " + java.time.LocalDateTime.now() + " - " + message);
    89→    }
    90→    
    91→    private void logError(String message) {
    92→        System.err.println("[ERROR] " + java.time.LocalDateTime.now() + " - " + message);
    93→    }
    94→    
    95→    private void startServer() {
    96→        try {
    97→            // Container-friendly server startup with configurable port
    98→            ServerSocket serverSocket = new ServerSocket(SERVER_PORT);
    99→            logInfo("Server started on port: " + SERVER_PORT);
   100→            logInfo("Server ready to accept connections...");
   101→            
   102→            // Add graceful shutdown handling for containers
   103→            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
   104→                logInfo("Shutting down server gracefully...");
   105→                try {
   106→                    serverSocket.close();
   107→                } catch (Exception e) {
   108→                    logError("Error during server shutdown: " + e.getMessage());
   109→                }
   110→            }));
   111→            
   112→            // Simulate server running
   113→            Thread.sleep(1000);
   114→            serverSocket.close();
   115→            
   116→        } catch (Exception e) {
   117→            logError("Failed to start server: " + e.getMessage());
   118→        }
   119→    }
   120→    
   121→    private void startHealthCheckServer() {
   122→        healthController = new HealthController();
   123→        healthController.startHealthCheckServer();
   124→        
   125→        // Add health check server to shutdown hook
   126→        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
   127→            logInfo("Shutting down health check server...");
   128→            if (healthController != null) {
   129→                healthController.stopHealthCheckServer();
   130→            }
   131→        }));
   132→    }
