/**
 * Initialize HikariCP connection pool for cloud-native database connectivity
 */
public void connect() {
    if (initialized) {
        logger.info("Database connection pool already initialized");
        return;
    }

    try {
        MDC.put("operation", "db-connect");
        logger.info("Initializing database connection pool...");

        // Configure HikariCP for cloud environments
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl(DB_URL);
        config.setUsername(DB_USERNAME);
        config.setPassword(DB_PASSWORD);

        // Cloud-optimized connection pool settings
        config.setMaximumPoolSize(Integer.parseInt(System.getenv().getOrDefault("DB_POOL_MAX_SIZE", "20")));
        config.setMinimumIdle(Integer.parseInt(System.getenv().getOrDefault("DB_POOL_MIN_IDLE", "5")));
        config.setConnectionTimeout(Long.parseLong(System.getenv().getOrDefault("DB_CONNECTION_TIMEOUT", "30000")));
        config.setIdleTimeout(Long.parseLong(System.getenv().getOrDefault("DB_IDLE_TIMEOUT", "600000")));
        config.setMaxLifetime(Long.parseLong(System.getenv().getOrDefault("DB_MAX_LIFETIME", "1800000")));
        config.setLeakDetectionThreshold(Long.parseLong(System.getenv().getOrDefault("DB_LEAK_DETECTION", "60000")));

        // Connection validation
        config.setConnectionTestQuery("SELECT 1");
        config.setValidationTimeout(5000);

        // Pool name for monitoring
        config.setPoolName("MiniAppHikariPool");

        // Create datasource
        dataSource = new HikariDataSource(config);
        initialized = true;

        logger.info("Database connection pool initialized successfully - URL: {}, Pool Size: {}",
            DB_HOST + ":" + DB_PORT + "/" + DB_NAME, config.getMaximumPoolSize());

        // Container-friendly cache connection
        connectToCache();

        // Container-friendly external service initialization
        initializeExternalServices();

    } catch (Exception e) {
        logger.error("Database connection pool initialization failed", e);
        throw new RuntimeException("Failed to initialize database connection pool", e);
    } finally {
        MDC.clear();
    }
}

/**
 * Get a connection from the pool
 */
public static Connection getConnection() throws SQLException {
    if (!initialized || dataSource == null) {
        throw new SQLException("Database connection pool not initialized");
    }
    return dataSource.getConnection();
}

