package com.test;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

/**
 * Cloud-ready database service with connection pooling and proper resource management
 */
public class DatabaseService {

    private static final Logger logger = LoggerFactory.getLogger(DatabaseService.class);

    // Container-friendly database configuration using environment variables
    private static final String DB_HOST = System.getenv().getOrDefault("DB_HOST", "localhost");
    private static final String DB_PORT = System.getenv().getOrDefault("DB_PORT", "3306");
    private static final String DB_NAME = System.getenv().getOrDefault("DB_NAME", "mini_app_db");
    private static final String DB_URL = "jdbc:mysql://" + DB_HOST + ":" + DB_PORT + "/" + DB_NAME
        + "?useSSL=true&requireSSL=false&serverTimezone=UTC";
    private static final String DB_USERNAME = System.getenv().getOrDefault("DB_USERNAME", "root");
    private static final String DB_PASSWORD = System.getenv().getOrDefault("DB_PASSWORD", "password123");

    // Container-friendly cache server configuration using environment variables
    private static final String REDIS_HOST = System.getenv().getOrDefault("REDIS_HOST", "redis");
    private static final int REDIS_PORT = Integer.parseInt(System.getenv().getOrDefault("REDIS_PORT", "6379"));

    // Container-friendly API endpoints using environment variables
    private static final String EXTERNAL_API_URL = System.getenv().getOrDefault("EXTERNAL_API_URL", "http://api.example.com:8080/v1");
    private static final String PAYMENT_SERVICE_URL = System.getenv().getOrDefault("PAYMENT_SERVICE_URL", "https://payment.internal.company.com/process");

    // Cloud-native connection pooling
    private static HikariDataSource dataSource;
    private static volatile boolean initialized = false;

    /**
     * Initialize HikariCP connection pool for cloud-native database connectivity
     */
    public void connect() {
        if (initialized) {
            logger.info("Database connection pool already initialized");
            return;
        }

        try {
            MDC.put("operation", "db-connect");
            logger.info("Initializing database connection pool...");

            // Configure HikariCP for cloud environments
            HikariConfig config = new HikariConfig();
            config.setJdbcUrl(DB_URL);
            config.setUsername(DB_USERNAME);
            config.setPassword(DB_PASSWORD);

            // Cloud-optimized connection pool settings
            config.setMaximumPoolSize(Integer.parseInt(System.getenv().getOrDefault("DB_POOL_MAX_SIZE", "20")));
            config.setMinimumIdle(Integer.parseInt(System.getenv().getOrDefault("DB_POOL_MIN_IDLE", "5")));
            config.setConnectionTimeout(Long.parseLong(System.getenv().getOrDefault("DB_CONNECTION_TIMEOUT", "30000")));
            config.setIdleTimeout(Long.parseLong(System.getenv().getOrDefault("DB_IDLE_TIMEOUT", "600000")));
            config.setMaxLifetime(Long.parseLong(System.getenv().getOrDefault("DB_MAX_LIFETIME", "1800000")));
            config.setLeakDetectionThreshold(Long.parseLong(System.getenv().getOrDefault("DB_LEAK_DETECTION", "60000")));

            // Connection validation
            config.setConnectionTestQuery("SELECT 1");
            config.setValidationTimeout(5000);

            // Pool name for monitoring
            config.setPoolName("MiniAppHikariPool");

            // Create datasource
            dataSource = new HikariDataSource(config);
            initialized = true;

            logger.info("Database connection pool initialized successfully - URL: {}, Pool Size: {}",
                DB_HOST + ":" + DB_PORT + "/" + DB_NAME, config.getMaximumPoolSize());

            // Container-friendly cache connection
            connectToCache();

            // Container-friendly external service initialization
            initializeExternalServices();

        } catch (Exception e) {
            logger.error("Database connection pool initialization failed", e);
            throw new RuntimeException("Failed to initialize database connection pool", e);
        } finally {
            MDC.clear();
        }
    }

    /**
     * Get a connection from the pool
     */
    public static Connection getConnection() throws SQLException {
        if (!initialized || dataSource == null) {
            throw new SQLException("Database connection pool not initialized");
        }
        return dataSource.getConnection();
    }

    private void connectToCache() {
        // Container-friendly Redis connection using environment variables
        logger.info("Connecting to Redis cache at: {}:{}", REDIS_HOST, REDIS_PORT);
        // Simulate cache connection
    }

    private void initializeExternalServices() {
        // Container-friendly external service URLs using environment variables
        logger.info("Initializing external API: {}", EXTERNAL_API_URL);
        logger.info("Initializing payment service: {}", PAYMENT_SERVICE_URL);
    }

    public void executeQuery(String sql) {
        MDC.put("operation", "db-query");
        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {

            // Container-friendly query timeout using environment variable
            int queryTimeout = Integer.parseInt(System.getenv().getOrDefault("DB_QUERY_TIMEOUT", "30"));
            stmt.setQueryTimeout(queryTimeout);

            logger.info("Executing query: {}", sql);
            stmt.execute();
            logger.debug("Query executed successfully");

        } catch (SQLException e) {
            logger.error("Query execution failed: {}", sql, e);
            throw new RuntimeException("Database query failed", e);
        } finally {
            MDC.clear();
        }
    }

    public void disconnect() {
        try {
            if (connection != null && !connection.isClosed()) {
                connection.close();
                System.out.println("Database connection closed");
            }
        } catch (SQLException e) {
            System.err.println("Failed to close database connection: " + e.getMessage());
        }
    }
}

