package com.test;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.net.ServerSocket;
import java.util.Properties;
import java.util.UUID;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;

/**
 * Cloud-ready Mini Java Application with distributed tracing and structured logging
 */
public class MiniApp {

    private static final Logger logger = LoggerFactory.getLogger(MiniApp.class);

    // Container-friendly port configuration
    private static final int SERVER_PORT = Integer.parseInt(System.getenv().getOrDefault("SERVER_PORT", "8080"));

    // Container-friendly configuration path using environment variables
    private static final String CONFIG_FILE_PATH = System.getenv().getOrDefault("CONFIG_PATH", "application.properties");
    private static final String LOG_LEVEL = System.getenv().getOrDefault("LOG_LEVEL", "INFO");

    // Application instance ID for distributed tracing
    private static final String INSTANCE_ID = System.getenv().getOrDefault("INSTANCE_ID", UUID.randomUUID().toString().substring(0, 8));

    private HealthController healthController;

    public static void main(String[] args) {
        // Initialize distributed tracing context
        String traceId = UUID.randomUUID().toString();
        MDC.put("traceId", traceId);
        MDC.put("instanceId", INSTANCE_ID);
        MDC.put("operation", "app-startup");

        logger.info("Starting Mini Java Application - Instance: {}, Trace: {}", INSTANCE_ID, traceId);

        try {
            MiniApp app = new MiniApp();
            app.initializeApplication();
            app.startHealthCheckServer();
            app.startServer();

            logger.info("Application startup completed successfully");
        } catch (Exception e) {
            logger.error("Application startup failed", e);
            System.exit(1);
        } finally {
            MDC.clear();
        }
    }

    private void initializeApplication() {
        MDC.put("operation", "app-init");
        logger.info("Initializing application components");

        try {
            // Load configuration from classpath or environment
            loadConfiguration();

            // Initialize structured logging
            initializeLogging();

            // Initialize database connection pool
            DatabaseService dbService = new DatabaseService();
            dbService.connect();

            logger.info("Application initialization completed");
        } catch (Exception e) {
            logger.error("Application initialization failed", e);
            throw new RuntimeException("Failed to initialize application", e);
        } finally {
            MDC.remove("operation");
        }
    }

    private void loadConfiguration() {
        MDC.put("operation", "config-load");
        try {
            // Container-friendly configuration loading with fallback
            Properties props = new Properties();

            // Try loading from classpath first (container-friendly)
            try (var stream = getClass().getClassLoader().getResourceAsStream(CONFIG_FILE_PATH)) {
                if (stream != null) {
                    props.load(stream);
                    logger.info("Configuration loaded from classpath: {}", CONFIG_FILE_PATH);
                } else {
                    // Fallback to file system if classpath loading fails
                    File configFile = new File(CONFIG_FILE_PATH);
                    if (configFile.exists()) {
                        props.load(new FileInputStream(configFile));
                        logger.info("Configuration loaded from file: {}", CONFIG_FILE_PATH);
                    } else {
                        logger.warn("Configuration file not found, using defaults: {}", CONFIG_FILE_PATH);
                    }
                }
            }

            logger.info("Configuration loaded successfully - {} properties", props.size());

        } catch (IOException e) {
            logger.error("Failed to load configuration from: {}", CONFIG_FILE_PATH, e);
            throw new RuntimeException("Configuration loading failed", e);
        } finally {
            MDC.remove("operation");
        }
    }

    private void initializeLogging() {
        MDC.put("operation", "logging-init");

        // Container-friendly structured logging configuration
        logger.info("Structured logging initialized - JSON format for cloud monitoring");
        logger.info("Log level: {}", LOG_LEVEL);

        // Log initialization message with trace context
        logger.info("Application logging configured for cloud environment - Instance: {}", INSTANCE_ID);

        MDC.remove("operation");
    }

    private void startServer() {
        try {
            // Container-friendly server startup with configurable port
            ServerSocket serverSocket = new ServerSocket(SERVER_PORT);
            logInfo("Server started on port: " + SERVER_PORT);
            logInfo("Server ready to accept connections...");

            // Add graceful shutdown handling for containers
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                logInfo("Shutting down server gracefully...");
                try {
                    serverSocket.close();
                } catch (Exception e) {
                    logError("Error during server shutdown: " + e.getMessage());
                }
            }));

            // Simulate server running
            Thread.sleep(1000);
            serverSocket.close();

        } catch (Exception e) {
            logError("Failed to start server: " + e.getMessage());
        }
    }

    private void startHealthCheckServer() {
        healthController = new HealthController();
        healthController.startHealthCheckServer();

        // Add health check server to shutdown hook
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            logInfo("Shutting down health check server...");
            if (healthController != null) {
                healthController.stopHealthCheckServer();
            }
        }));
    }
}

